// Correlation Heatmap — Heatmap, route: jsx
// Source: original:gaps/correlation-heatmap
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from correlationHeatmap ----
// Seeded wellbeing survey: 60 observations of 7 variables generated from two latent
// factors plus noise, so the correlation matrix shows visible blocks — an exercise/
// sleep/mood cluster, a stress/caffeine cluster, and one strong negative pair
// (exercise vs resting heart rate). Mulberry32 PRNG for determinism.
function mulberry32(seed: number) {
  let a = seed;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function randomNormal(rng: () => number) {
  const u1 = rng();
  const u2 = rng();
  return Math.sqrt(-2 * Math.log(1 - u1)) * Math.cos(2 * Math.PI * u2);
}

const rng = mulberry32(20260822);
const OBSERVATIONS = 60;

const rows = Array.from({ length: OBSERVATIONS }, () => {
  const lifestyle = randomNormal(rng); // latent: healthy-lifestyle factor
  const stimulation = randomNormal(rng); // latent: stimulation factor
  const noise = () => randomNormal(rng);
  return [
    lifestyle + 0.3 * noise(), // Exercise
    0.8 * lifestyle + 0.5 * noise(), // Sleep
    -0.9 * lifestyle + 0.35 * noise(), // Resting HR — the strong negative pair
    0.85 * stimulation - 0.3 * lifestyle + 0.4 * noise(), // Stress
    0.8 * stimulation + 0.5 * noise(), // Caffeine
    0.6 * lifestyle - 0.4 * stimulation + 0.5 * noise(), // Focus
    0.7 * lifestyle - 0.5 * stimulation + 0.4 * noise() // Mood
  ];
});

const wellbeingSurvey: { variables: string[]; rows: number[][] } = {
  variables: ['Exercise', 'Sleep', 'Resting HR', 'Stress', 'Caffeine', 'Focus', 'Mood'],
  rows
};

const MARGIN = { top: 80, right: 8, bottom: 8, left: 80 };
const MIN_CELL_FOR_TEXT = 30;

const formatR = d3.format('.2f');

/** Raw observations: each row is one observation, columns align with `variables`. */
export type Data = { variables: string[]; rows: number[][] };

function pearson(a: number[], b: number[]): number {
  const meanA = d3.mean(a) ?? 0;
  const meanB = d3.mean(b) ?? 0;
  let numerator = 0;
  let sumA = 0;
  let sumB = 0;
  for (let i = 0; i < a.length; i++) {
    const da = a[i] - meanA;
    const db = b[i] - meanB;
    numerator += da * db;
    sumA += da * da;
    sumB += db * db;
  }
  const denominator = Math.sqrt(sumA * sumB);
  return denominator === 0 ? 0 : numerator / denominator;
}

export default function CorrelationHeatmap({ data = wellbeingSurvey, width }: { data?: Data; width: number }) {
  const side = Math.max(1, width - MARGIN.left - MARGIN.right);
  const height = side + MARGIN.top + MARGIN.bottom;

  const matrix = useMemo(() => {
    const columns = data.variables.map((_, i) => data.rows.map((row) => row[i]));
    return columns.map((a) => columns.map((b) => pearson(a, b)));
  }, [data]);

  const band = useMemo(
    () =>
      d3
        .scaleBand<string>()
        .domain(data.variables)
        .range([0, side])
        .paddingInner(0.04),
    [data, side]
  );

  // Diverging, midpoint pinned at 0: red negative, near-white zero, blue positive.
  const color = useMemo(
    () => d3.scaleSequential(d3.interpolateRdBu).domain([-1, 1]),
    []
  );

  const showText = band.bandwidth() >= MIN_CELL_FOR_TEXT;

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Correlation heatmap of Pearson correlations between seven wellbeing variables, blue for positive and red for negative, with exercise and resting heart rate strongly negative"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        {matrix.map((rowValues, i) =>
          rowValues.map((r, j) => {
            const cx = (band(data.variables[j]) ?? 0) + band.bandwidth() / 2;
            const cy = (band(data.variables[i]) ?? 0) + band.bandwidth() / 2;
            return (
              <g key={`${data.variables[i]}-${data.variables[j]}`}>
                <rect
                  x={band(data.variables[j]) ?? 0}
                  y={band(data.variables[i]) ?? 0}
                  width={band.bandwidth()}
                  height={band.bandwidth()}
                  fill={color(r)}
                />
                {showText && (
                  <text
                    x={cx}
                    y={cy}
                    dy="0.32em"
                    textAnchor="middle"
                    fontSize={11}
                    fill={Math.abs(r) > 0.6 ? '#f4f4f4' : '#1c1c1c'}
                  >
                    {formatR(r)}
                  </text>
                )}
              </g>
            );
          })
        )}
        {data.variables.map((variable) => {
          const center = (band(variable) ?? 0) + band.bandwidth() / 2;
          return (
            <g key={variable}>
              <text
                x={-8}
                y={center}
                dy="0.32em"
                textAnchor="end"
                fontSize={11}
                fill="var(--text)"
              >
                {variable}
              </text>
              <text
                transform={`translate(${center},-8) rotate(-45)`}
                textAnchor="start"
                fontSize={11}
                fill="var(--text)"
              >
                {variable}
              </text>
            </g>
          );
        })}
      </g>
    </svg>
  );
}
